def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        bid = min(budget, DAILY_SALARY * 0.35)
        return float(max(0.0, bid))

    prev_bids = []
    threat_bids = []
    cindy_bid = None
    strongest_pressure = 0.0

    for agent_id, opp in opponents_status.items():
        if not opp.get('alive'):
            continue
        prev = opp.get('previous_trace', {})
        pbid = prev.get('bid')
        if pbid is not None:
            prev_bids.append(float(pbid))
            pressure = float(pbid)
            if opp.get('budget', 0) < DAILY_SALARY * 0.8:
                pressure *= 0.75
            if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
                pressure *= 1.2
            if pressure > strongest_pressure:
                strongest_pressure = pressure
            threat_bids.append(pressure)
        if agent_id == 'Cindy' and pbid is not None:
            cindy_bid = float(pbid)

    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0
    max_prev = max(prev_bids) if prev_bids else 0.0
    max_threat = max(threat_bids) if threat_bids else 0.0

    supply_ratio = (float(supply) - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)
    if supply_ratio < 0:
        supply_ratio = 0.0
    if supply_ratio > 1:
        supply_ratio = 1.0

    scarcity = 1.0 - supply_ratio

    if hp <= 2 or no_water_days >= 2:
        base = DAILY_SALARY * 0.98
    elif hp <= 4 or no_water_days >= 1:
        base = DAILY_SALARY * (0.78 + 0.12 * scarcity)
    else:
        base = DAILY_SALARY * (0.34 + 0.18 * scarcity)

    if cindy_bid is not None:
        target = cindy_bid + (2.0 if hp <= 4 or no_water_days >= 1 else -18.0 + 10.0 * scarcity)
    elif max_threat > 0:
        target = max_threat + (1.5 if hp <= 4 or no_water_days >= 1 else -12.0 + 8.0 * scarcity)
    else:
        target = base

    bid = max(base, target)

    if hp > 5 and no_water_days == 0 and supply >= 22:
        bid = min(bid, DAILY_SALARY * 0.32)

    if max_prev >= DAILY_SALARY * 1.8 and hp > 4 and no_water_days == 0:
        bid = min(bid, DAILY_SALARY * 0.28)

    reserve_days = 3 if day < 8 else 1
    reserve = reserve_days * DAILY_SALARY * 0.45
    spendable = budget - reserve
    if spendable < DAILY_SALARY * 0.2:
        spendable = max(budget * 0.5, 0.0)

    bid = min(bid, spendable)

    if hp <= 3 or no_water_days >= 1:
        bid = max(bid, min(budget, DAILY_SALARY * 0.72))

    if day >= 9:
        bid = max(bid, min(budget, DAILY_SALARY * (0.55 + 0.2 * scarcity)))

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Identify alive opponents
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    # If no opponents, bid conservatively
    if not alive_opps:
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    # Read yesterday bids from immediate previous_trace only
    prev_bids = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev['bid']))
            except Exception:
                pass

    # Pressure estimate: how aggressive others were yesterday
    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Base bid depends on supply: higher supply means we can bid slightly less while still staying competitive
    # Normalize supply into [0,1]
    denom = (MAX_SUPPLY - MIN_SUPPLY)
    if denom <= 0:
        s_norm = 0.5
    else:
        s_norm = (supply - MIN_SUPPLY) / denom
        if s_norm < 0.0:
            s_norm = 0.0
        if s_norm > 1.0:
            s_norm = 1.0

    # Convert supply into a rough expected water share pressure.
    # At supply ~15, water is scarce; at 25, less scarce.
    scarcity = 1.0 - s_norm

    # My urgency: low hp => bid harder to avoid death spiral
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])

    # If opponents were bidding near salary yesterday, they likely secured water; match more aggressively.
    # Cindy survived with moderate bids; Alex died with high bids -> both indicate bidding matters.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # Match/contest
        if hp > 3:
            target = DAILY_SALARY * (0.35 + 0.25 * scarcity)
        else:
            target = DAILY_SALARY * (0.85 + 0.1 * scarcity)
    else:
        # Otherwise, bid enough to not be the low bidder (avoid Eric-like early death)
        if hp <= 2:
            target = DAILY_SALARY * (0.75 + 0.15 * scarcity)
        else:
            target = DAILY_SALARY * (0.50 + 0.25 * scarcity)

    # Also consider how many days I can survive without water; if already low, bid higher.
    try:
        no_water_days = int(my_status.get('no_water_days', 0))
    except Exception:
        no_water_days = 0
    if no_water_days <= 1:
        target *= 1.15

    # Ensure we don't exceed budget; also keep a floor to avoid going too low.
    # Floor chosen to be meaningfully above typical low bids.
    floor_bid = DAILY_SALARY * (0.35 + 0.1 * scarcity)
    bid = float(max(floor_bid, target))

    if budget <= 0:
        return 0.0
    if bid > budget:
        bid = budget

    # Safety: bid cannot be negative
    if bid < 0.0:
        bid = 0.0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    bid = DAILY_SALARY * 0.85

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if my_status['hp'] <= 3:
            bid = max(highest_prev_bid + 5.0, DAILY_SALARY * 1.15)
        elif my_status['hp'] <= 6:
            bid = max(highest_prev_bid + 2.0, DAILY_SALARY * 1.0)
        else:
            bid = max(highest_prev_bid * 0.98, DAILY_SALARY * 0.85)
    else:
        if my_status['hp'] <= 3:
            bid = DAILY_SALARY * 1.1
        elif my_status['hp'] <= 6:
            bid = DAILY_SALARY * 0.95
        else:
            bid = DAILY_SALARY * 0.8

    days_left = EPISODE_DAYS - day_context['day']
    if days_left <= 2:
        if my_status['hp'] <= days_left + 1:
            bid = max(bid, DAILY_SALARY * 1.25)
        else:
            bid = max(bid, DAILY_SALARY * 0.9)

    bid = min(bid, my_status['budget'])

    if bid <= 0 and my_status['budget'] > 0:
        bid = min(my_status['budget'], 1.0)
    elif bid < DAILY_SALARY * 0.05 and my_status['budget'] > DAILY_SALARY * 0.05:
        bid = DAILY_SALARY * 0.05

    return bid

